      $('#wander-shell').addEventListener('click',flowClick);$('#wander-dialog').addEventListener('pointerdown',flowPrepPointerDown);$('#wander-shell').addEventListener('pointerdown',flowPointerDown);$('#wander-dialog').addEventListener('cancel',e=>{e.preventDefault();if(flowConfirm&&!flowBusy())flowAction('utility-close');else toast('请先完成当前选择');});$('#board').oncontextmenu=e=>{e.preventDefault();if(battle||!flowCanEdit())return;const i=at(...boardPoint(e));if(i){chosen=i.uid;flowConfirm={type:'recycle',uid:i.uid};syncFlowDialog(true);}};
