  function flowFlash(inst,kind='place'){const board=$('#board');if(!board)return;$('#w-merge-flare')?.remove();const box=board.getBoundingClientRect(),d=itemById.get(inst.id),fp=flowFootprint(d,inst.rotation),el=document.createElement('div');el.id='w-merge-flare';el.className=kind;el.textContent=kind==='merge'?'合成':'入阵';el.style.cssText=`left:${box.left+(inst.x===null?3:inst.x+fp.w/2)*box.width/COLS}px;top:${box.top+(inst.y===null?3:inst.y+fp.h/2)*box.height/ROWS}px`;document.body.append(el);flowMotion={remaining:kind==='merge'?.5:.18};$('#wander-shell').dataset.busy='true';$('#w-next').disabled=true;}
