  function flowCompose(a,b,where=null){if(a.salePrice!=null||b.salePrice!=null)return false;const awake=TR.carried(state).flatMap(id=>WanderAwakening.pairs(state,id)).find(p=>(p.source===a.uid&&p.material===b.uid)||(p.source===b.uid&&p.material===a.uid));if(awake)return startAwaken(awake);const choices=TR.candidates(state,a,b).filter(r=>r.arrProductID.every(id=>itemById.has(id)));if(!choices.length)return false;if(choices.length>1){flowConfirm={type:'recipe-choice',uids:[a.uid,b.uid],where};syncFlowDialog(true);return true;}return flowCraft(choices[0].iFormID,[a.uid,b.uid],where);}
  function flowCraft(id,uids=null,where=null){if(!flowCanEdit())return false;const p=TR.plan(state,id,uids);if(p.error){toast(p.error);return false;}const product=TR.product(p.recipe);if(!itemById.has(product)){toast('该配方产物资源尚未接入');return false;}const offer=p.materials.find(i=>i.offer)?.offer,inst={uid:++uid,id:product,x:null,y:null,rotation:0,teacherId:p.teacherId,...(offer?{offer}:{})};state.inventory=state.inventory.filter(i=>!p.materials.includes(i));if(where&&fits(inst,...where,0)){inst.x=where[0];inst.y=where[1];}state.inventory.push(inst);const r=flowRun();if(r){r.craftLog||=[];r.craftLog.push({recipe:id,teacherId:p.teacherId,materials:p.materials.map(i=>({uid:i.uid,id:i.id})),product:{uid:inst.uid,id:product},provenance:'local-result/source-recipe'});}chosen=inst.uid;angle=0;flowConfirm=null;save();refreshFlow();flowFlash(inst,'merge');toast('合成成功 · '+itemById.get(product).name);return true;}
  function flowMergeTarget(inst,x,y){const cells=shape(itemById.get(inst.id),angle).map(([a,b])=>[x+a,y+b]);if(cells.some(([a,b])=>a<0||a>=COLS||b<0||b>=ROWS||(tab==='wander'&&flowRun()&&!WT.open(state,a,b))))return null;const hits=state.inventory.filter(i=>i!==inst&&i.x!==null&&occupied(i).some(p=>cells.some(c=>c[0]===p[0]&&c[1]===p[1])));return hits.length===1&&(flowRecipe(inst,hits[0])||TR.carried(state).some(id=>WanderAwakening.pairs(state,id).some(p=>(p.source===inst.uid&&p.material===hits[0].uid)||(p.material===inst.uid&&p.source===hits[0].uid))))&&occupied(hits[0]).filter(p=>cells.some(c=>c[0]===p[0]&&c[1]===p[1])).length/Math.min(cells.length,occupied(hits[0]).length)>=.5?hits[0]:null;}
