  function flowAction(action,value){if(action==='utility-close'){if(flowConfirm?.type==='book-item'){const target=flowConfirm.returnTo;return target==='bag'?flowAction('bag-back'):flowAction('book-tab',target);}if(flowConfirm?.type==='bag-trait')return flowAction('bag-back');action='cancel-confirm';}if(sourceAction(action,value))return;if(eventAction(action,value))return;if(toolAction(action,value))return;const r=flowRun();if(action==='help'){$('#help').click();return;}if(action==='next'){if(flowConfirm)return;if(flowBusy())return toast('法宝整理中，请稍候');if(flowDrag?.active)return toast('请先摆放当前法宝！');if(!r)return newRun();if(battle){window.advanceTime(60000);return;}if(r.reward){if(r.rewardView==='event')return showRewardSelection();return finishReward();}if(r.popup){if(r.popup.type==='story')return advanceFlowQueue();syncFlowDialog();return;}if(r.phase==='prepare'){r.popup={type:r.prepare};save();refreshFlow();return;}if(r.phase==='complete'||r.phase==='defeat'){r.popup={type:'result'};refreshFlow();return;}if(r.phase==='node-done'){if(r.step===flowRoute().length-1)return finishWander(false);r.step++;}return beginNode();}
    if(action==='reward-open')return showRewardSelection();if(action==='leave'){if(equipmentReady()&&r?.reward)return closeRewardSelection();if(!canLeaveWander())return;switchTab('sect');return;}
    if(action==='recipes'){if(flowCanEdit()){flowConfirm={type:'recipes'};syncFlowDialog(true);}return;}
    if(action==='craft'){const p=flowConfirm;if(!p||!['recipes','recipe-choice','book'].includes(p.type))return;flowConfirm=null;$('#wander-dialog')?.close();flowCraft(+value,p.uids||null,p.where||null);return;}
    if(['rotate','return','merge','detail'].includes(action)){if(!flowCanEdit())return;const i=state.inventory.find(i=>i.uid===chosen);if(!i)return toast('请先选中法宝');if(action==='rotate'){angle=(angle+1)%4;drawBoard();return;}if(action==='return'){flowConfirm={type:'recycle',uid:i.uid};syncFlowDialog(true);return;}if(action==='merge'){const other=state.inventory.find(j=>j!==i&&flowRecipe(i,j));if(!other)return toast('当前没有可用的合成材料');flowCompose(i,other);return;}if(action==='detail'){flowConfirm={type:'item',uid:i.uid};syncFlowDialog();return;}}
    if(!r||flowBusy())return;
    if(action==='point'){const [axis,delta]=value.split(',').map(Number),remaining=5-r.config.points.reduce((a,b)=>a+b,0);if(delta>0&&remaining<=0)return toast('属性点已分配完');r.config.points[axis]=Math.max(0,r.config.points[axis]+delta);save();syncFlowDialog(true);return;}
    if(action==='point-reset'){r.config.points=[0,0,0,0];save();syncFlowDialog(true);return;}if(action==='back-birth'){r.prepare='birth';r.popup={type:'birth'};if(state.admission?.profile){state.admission.phase='birth';save();render();return;}save();refreshFlow();return;}if(action==='point-random'){r.config.points=[2,1,2,0];save();syncFlowDialog(true);return;}
    if(action==='birth-next'){if(r.config.points.reduce((a,b)=>a+b,0)!==5)return toast('点数未分配完，请继续分配！');state.selected=r.config.disciple;r.prepare='seed';r.popup={type:'seed'};save();refreshFlow();return;}
    if(action==='disciple'){r.config.disciple=+value;state.selected=+value;save();syncFlowDialog(true);return;}
    if(action==='slot'){flowSlot=value;syncFlowDialog(true);return;}
    if(action==='filter'){flowFilter=+value;syncFlowDialog(true);return;}
    if(action==='seed'){const id=+value;if(flowSlot==='seed'&&r.config.sub===id)r.config.sub=null;if(flowSlot==='sub'&&r.config.seed===id)return toast('主修与辅修请选择不同功法');r.config[flowSlot]=r.config[flowSlot]===id?null:id;save();syncFlowDialog(true);return;}
    if(action==='seed-next'){if(!r.config.seed)return toast('请选择主修功法');r.prepare='teacher';r.popup={type:'teacher'};save();refreshFlow();return;}
    if(action==='back-seed'){r.popup={type:'seed'};r.prepare='seed';save();syncFlowDialog(true);return;}
    if(action==='teacher'){const id=+value;if(r.config.teachers.includes(id))r.config.teachers=r.config.teachers.filter(x=>x!==id);else if(r.config.teachers.length<2)r.config.teachers.push(id);else return toast('最多携带两位长老');save();syncFlowDialog(true);return;}
    if(action==='depart'){if(!r.config.teachers.length){flowConfirm={type:'no-teacher'};syncFlowDialog(true);return;}return depart();}
    if(action==='depart-anyway')return depart();
    if(action==='cancel-confirm'){flowConfirm=null;refreshFlow();return;}
    if(action==='discard-confirm'){flowConfirm=null;return beginRewardAdvance();}
    if(action==='popup-next'){if(!r.popup||!['story','wheel'].includes(r.popup.type))return;if(r.popup.type==='story'&&r.step===0&&r.phase==='prepare')return;return advanceFlowQueue();}
    if(action==='ability'){
      const p=r.popup;if(p?.type!=='ability'||r.pending||!p.options.includes(+value))return;
      if((p.selectCount||1)>1){p.selectedIds??=[];p.selectedIds=p.selectedIds.includes(+value)?p.selectedIds.filter(id=>id!==+value):[...p.selectedIds.slice(-(p.selectCount-1)),+value];save();syncFlowDialog(true);return;}
      r.pending={kind:'ability',elapsed:0,duration:.45,id:+value};save();refreshFlow();return;
    }
    if(action==='ability-confirm'){const p=r.popup;if(p?.type!=='ability'||r.pending||(p.selectedIds||[]).length!==p.selectCount)return;for(const id of p.selectedIds)if(!r.abilities.includes(id))r.abilities.push(id);eventRecord('神通','领悟 '+p.selectedIds.map(id=>W.abilities.find(a=>a.id===id).name).join('、'));return advanceFlowQueue();}
    if(action==='ability-refresh'||action==='ability-refresh-confirm'){
      if(action.endsWith('confirm')&&flowConfirm?.type!=='ability-cost')return;
      EV.init(r.popup,r,state);const index=action.endsWith('confirm')?flowConfirm.index:+value;
      const err=EV.refreshAbility(r.popup,r,state,index,action.endsWith('confirm'));
      if(err==='confirm'){flowConfirm={type:'ability-cost',index};syncFlowDialog(true);return;}
      if(err)return toast(err);flowConfirm=null;save();refreshFlow();return;
    }
    if(action==='source-choice'){const p=r.popup;if(p?.type!=='source-choice'||r.pending)return;const option=EV.options(p,stats().power,hero().name).find(o=>o.id===+value);if(!option?.enabled)return toast('未满足选择条件');const e=EV.data.events[p.sourceId];eventRecord('奇遇选择',option.label);r.queue.unshift(EventLibrary.action(e['arrAction'+option.id]));return advanceFlowQueue();}
    if(action==='pet'){const p=r.popup;if(p?.type!=='pet'||r.pending)return;const i=+value;if(!Number.isInteger(i)||!p.options[i])return;p.selected=p.selected===i?null:i;save();syncFlowDialog(true);return;}
    if(action==='pet-info'){const p=r.popup;if(p?.type!=='pet'||!p.options[+value])return;flowConfirm={type:'pet-info',id:p.options[+value].id};syncFlowDialog(true);return;}
    if(action==='pet-confirm'){const p=r.popup;if(p?.type!=='pet'||p.selected===null||!p.options[p.selected]||r.pending)return toast('请选择灵宠');const opt=p.options[p.selected],pet=EV.data.pets.find(x=>x.id===opt.id);const owned=opt.owned?(state.pets||[]).find(x=>x.uid===opt.uid):null;if(opt.owned&&!owned)return toast('灵宠已不可用');const instance=owned||{id:pet.id,uid:++uid,level:1};if(!owned)(state.pets??=[]).push(instance);r.config.pet=pet.name;r.config.petId=pet.id;r.config.petUid=instance.uid;hero().petUid=instance.uid;eventRecord('灵宠相伴',pet.name+'已随行');return advanceFlowQueue();}
    if(action==='godexam'){if(r.popup?.type!=='godexam')return;r.popup.type='godexam-running';r.examElapsed=0;save();syncFlowDialog(true);return;}
    if(action==='wheel'){if(r.popup?.type!=='wheel'||r.popup.rolled)return;r.popup.rolled=true;r.blessing=(r.blessing||0)+.05;r.popup.text='老祖赐福，攻击提升 5%';save();syncFlowDialog(true);return;}
    if(action==='finish-result'){if(!r.settled)return;r.popup={type:'end-detail'};save();syncFlowDialog(true);return;}
    if(action==='rebirth-old'||action==='rebirth-new'){if(state.rebirth?.stage!=='compare')return;state.wanderCompleted=(state.wanderCompleted??state.cleared??0)+1;if(r.phase==='complete'&&!r.early){state.cleared++;if(state.homeV26)state.homeV26.maxWanderDifficulty=Math.max(state.homeV26.maxWanderDifficulty||0,state.admission?.difficulty||1);}DiscipleAdvanced.chooseRebirth(state,action==='rebirth-old'?'old':'new');chosen=null;flowConfirm=null;save();switchTab('disciples');return;}if(action==='finish-run'){if(state.rebirth?.stage==='compare'){r.popup={type:'rebirth-compare'};refreshFlow();return;}if(!r.settled)return;const graduate=state.disciples[r.config.disciple];graduate.journey=JSON.parse(JSON.stringify({config:r.config,abilities:r.abilities,inventory:state.inventory,openCells:[...WanderTools.data(state).baseCells,...WanderTools.data(state).opened],stats:stats(),report:r.lastBattleReport,result:r.phase==='complete'?'通关':'未通关'}));graduate.journey.baseStats=stats(graduate,false);graduate.sourcePower=stats().power;graduate.isWanderFinish=true;if(DiscipleAdvanced.completeRebirth(state,graduate)){r.popup={type:'rebirth-compare'};save();refreshFlow();return;}state.wanderCompleted=(state.wanderCompleted??state.cleared??0)+1;if(r.phase==='complete'&&!r.early){state.cleared++;if(state.homeV26)state.homeV26.maxWanderDifficulty=Math.max(state.homeV26.maxWanderDifficulty||0,state.admission?.difficulty||1);}state.run=null;chosen=null;flowConfirm=null;save();refreshFlow();return;}
    if(action==='battle-arrange'){r.popup=null;r.phase='battle-ready';save();refreshFlow();return;}
    if(action==='resume-battle'){r.popup=null;startBattle();return;}
  }
  function petTurn(b){
    for(const e of PetBattle.apply(state,b)){const label={damage:'造成伤害',heal:'恢复生命',shield:'获得护盾',sacrifice:'消耗生命',disarm:'缴械', 'break-shield':'削减护盾','refresh-equipment':'刷新法宝','counter-buff':'反击增伤','rage-critical-weaken':'压制怒气与暴击','stun-damage-buff':'击晕增伤','blood-curse':'附加血咒','rage':'恢复怒气'}[e.kind]||e.kind;log.push('灵宠 · '+label+' '+e.value);if(e.kind==='damage')combatCue('player',e.value,false);}
  }
  function renderPetCombat(){const p=PetBattle.selected(state);let el=$('#we-combat-pet');if(!p||!battle){el?.remove();return;}if(!el){el=document.createElement('div');el.id='we-combat-pet';$('#w-world')?.append(el);}const icon=EV.data.pets.find(x=>x.id===p.id)?.icon;el.innerHTML=`${icon?`<img src="${icon}" alt="${escape(p.pet.szName)}">`:''}<span>${escape(p.pet.szName)}<small>${escape(p.skill.szName)} · 护盾 ${Math.round(battle.playerShield||0)}</small></span>`;}
  function eventRecord(title,text){const r=flowRun();(r.records??=[]).push({step:r.step,title,text});r.history.push(title+' · '+text);}
  function applyEventPrize(id){const r=flowRun(),p=EventLibrary.prize(id);if(!p){throw Error('未解析的奖励 '+id);}r.eventBonuses??={};for(let i=0;i<(p.arrDiscipleProp||[]).length;i+=2){const k=p.arrDiscipleProp[i],v=p.arrDiscipleProp[i+1];r.eventBonuses[k]=(r.eventBonuses[k]||0)+v;}for(let i=0;i<(p.arrItem1||[]).length;i++){const item=p.arrItem1[i],n=Math.max(0,p.arrNum1?.[i]||1);if(item===1)state.gold+=n;else if(item===2)state.crystal=(state.crystal||0)+n;else{state.goods??={};state.goods[item]=(state.goods[item]||0)+n;}}eventRecord('获得奖励',(p.arrDiscipleProp||[]).filter((_,i)=>i%2===0).map((k,i)=>(COMBAT_EFFECTS_DATA.attributes[k]||k)+' '+(p.arrDiscipleProp[i*2+1]/100)+'%').join('、')||'资源奖励已入账');r.hp=Math.min(r.hp,stats().hp);}
  function handleSourceTask(task){const r=flowRun();if(task.type==='source-dispatch'){r.sourceSteps=(r.sourceSteps||0)+1;if(r.sourceSteps>128){r.queue=[];eventRecord('事件结束','本段奇遇已结束');}else r.queue.unshift(...EventLibrary.expand(task.sourceId,hero().name));save();advanceFlowQueue();return true;}
    if(task.type==='source-battle'){r.sourceBattle=true;startBattle();return true;}
    if(task.type!=='source-effect')return false;const a=task.action;
    if(a[0]===4){eventRecord('历练受挫','奇遇中遭遇不测');r.hp=0;finishWander(true);return true;}
    if(a[0]===3||a[0]===2)applyEventPrize(a[1]);
    if(a[0]===8)r.hp=Math.max(1,Math.min(stats().hp,Math.floor(r.hp+(a[1]===2003?stats().hp:r.hp)*(a[2]||0)/10000+(a[3]||0))));
    if(a[0]===9)r.hp=Math.min(stats().hp,r.hp+Math.round((stats().hp-r.hp)*(a[1]||0)/10000));
    if(a[0]===6){const t=WT.data(state),cells=WANDER_TOOLS_DATA.WanderPackageLevel.map(x=>x.iUnlockPos).filter(x=>!t.baseCells.includes(x)&&!t.opened.includes(x)).slice(0,Math.max(0,a[1]||0));t.baseCells.push(...cells);eventRecord('背包扩容','开启 '+cells.length+' 格');}
    if(a[0]===7||a[0]===5)r.queue.unshift({type:'equipment',total:1,title:'奇遇奖励'});
    save();advanceFlowQueue();return true;
  }
  function sourceAction(action,value){if(!action.startsWith('source-')||action==='source-choice')return false;const r=flowRun(),p=r?.popup;if(!p||r.pending||battle||flowConfirm)return true;
    if(action==='source-judge'&&p.type==='source-judge'){const e=EventLibrary.data.events[p.sourceId],won=stats().power>=p.required;eventRecord('战力判定',won?'考验成功':'考验未通过');const a=e['arrAction'+(won?0:1)];if(a?.length)r.queue.unshift(EventLibrary.action(a));advanceFlowQueue();return true;}
    if(action==='source-wheel'&&p.type==='source-wheel'&&!p.rolled){const wheel=EventLibrary.data.wheels[p.wheelId];if(!wheel?.arrItemID?.length)return true;const id=EventLibrary.weighted(wheel.arrItemID,wheel.arrCliProb),index=wheel.arrItemID.indexOf(id);p.rolled=true;p.prizeId=id;p.result=(wheel.arrEventName.split('#')[index]||'机缘').replace(/<[^>]*>/g,'');
      if(EventLibrary.prize(id)){applyEventPrize(id);p.result+=' · 奖励已入账';}
      else if(wheel.szName.includes('装备')){p.rewardTask={type:'equipment',title:p.result+' · 转盘法宝',quality:Math.max(1,Math.min(4,wheel.arrQuality[index]||2)),total:1};p.result+=' · 领取法宝';}
      else{const rate=Math.max(1,wheel.arrQuality[index]||1)*100;r.eventBonuses??={};for(const k of [2004,2005,2006])r.eventBonuses[k]=(r.eventBonuses[k]||0)+rate;p.result+=' · 攻防生命提升 '+rate/100+'%';eventRecord('转盘奖励',p.result);}
      save();syncFlowDialog(true);return true;}

    if(action==='source-dig'&&p.type==='source-dig'){const tile=+value;if(!Number.isInteger(tile)||tile<0||tile>=9||p.opened.includes(tile)||p.left<=0)return true;if(state.gold<p.cost){toast('灵石不足');return true;}state.gold-=p.cost;p.left--;p.opened.push(tile);eventRecord('挖宝','消耗 '+p.cost+' 灵石，挖开一处遗迹');const reward=Math.random()<.65;r.queue.unshift({...p});if(reward)r.queue.unshift({type:'equipment',title:'挖宝所得',total:1});else r.queue.unshift({type:'story',title:'挖宝',text:'此处未发现法宝。'});advanceFlowQueue();return true;}
    if(action==='source-alchemy-start'&&p.type==='source-alchemy'&&!p.running&&p.round<3){p.running=true;p.elapsed=0;save();syncFlowDialog(true);return true;}
    if(action==='source-alchemy-stop'&&p.type==='source-alchemy'&&p.running){p.running=false;const pos=(Math.sin(p.elapsed*4)+1)*50;p.score+=Math.abs(pos-50)<12?2:Math.abs(pos-50)<28?1:0;p.round++;save();syncFlowDialog(true);return true;}
    if(action==='source-upgrade'&&p.type==='source-upgrade'){const i=state.inventory.find(i=>i.uid===+value&&i.x!==null&&i.salePrice==null);if(!i)return true;if(state.gold<p.cost){toast('灵石不足');return true;}const old=itemById.get(i.id),next=[...itemById.values()].find(d=>d.element===old.element&&d.quality===old.quality+1&&JSON.stringify(d.shape)===JSON.stringify(old.shape));if(!next){toast('该法宝暂无可用进阶');return true;}state.gold-=p.cost;i.id=next.id;eventRecord('法宝升级',old.name+' → '+next.name);advanceFlowQueue();return true;}
    if(action==='source-slots'&&p.type==='source-slots'&&p.spins<3){if(state.gold<p.cost){toast('灵石不足');return true;}state.gold-=p.cost;p.spins++;const win=Math.random()<.6;eventRecord('天机转轮',win?'获得法宝':'本次未中奖');r.queue.unshift({...p});if(win)r.queue.unshift({type:'equipment',title:'转轮奖励',total:1});else r.queue.unshift({type:'story',title:'转轮结果',text:'转轮停下，未发现奖励。'});advanceFlowQueue();return true;}
    if(action==='source-finish'&&['source-wheel','source-dig','source-alchemy','source-upgrade','source-slots'].includes(p.type)){if(p.type==='source-wheel'&&!p.rolled)return true;if(p.rewardTask)r.queue.unshift(p.rewardTask);if(p.type==='source-alchemy'){r.hp=Math.min(stats().hp,r.hp+Math.round(stats().hp*(.05+p.score*.03)));eventRecord('炼丹结束','炼丹评分 '+p.score+'，服丹恢复生命');}advanceFlowQueue();return true;}
    return true;
  }
  function openShop(task){const r=flowRun();r.popup=null;r.phase='reward';r.rewardView='equipment';r.reward={title:task.title,sourceId:task.sourceId,shop:true,refreshes:0,batch:0,total:1,token:r.token+'-shop-'+r.step};stockShop();save();refreshFlow();}
  function stockShop(){const r=flowRun(),rw=r.reward;state.inventory=state.inventory.filter(i=>i.offer!==rw.token||i.salePrice==null);const pool=D.items.filter(i=>i.id>=110000&&i.id<180000&&i.quality>=2&&i.quality<=4);for(const id of EV.draw(pool.map(i=>i.id),3)){const d=itemById.get(id);state.inventory.push({uid:++uid,id,x:null,y:null,rotation:0,offer:rw.token,salePrice:d.quality*10});}}
  function renderShopControls(){const shell=$('#wander-shell');if(!shell)return;let bar=$('#we-shop');if(!bar){bar=document.createElement('div');bar.id='we-shop';$('#w-reward').before(bar);}const rw=flowRun()?.reward;bar.hidden=!(rw?.shop&&flowRun().rewardView!=='event');if(bar.hidden)return;const cfg=EV.data.events[rw.sourceId],max=cfg.arrParam.length-2,cost=cfg.arrParam[Math.min(2+rw.refreshes,cfg.arrParam.length-1)];bar.innerHTML=`<span>淘宝斋 · 灵石 ${state.gold}</span><button data-flow="shop-refresh" ${rw.refreshes>=max?'disabled':''}>刷新 ${rw.refreshes}/${max} · ${cost} 灵石</button>`;}
  function eventAction(a,v){if(!['shop-refresh','shop-buy-confirm'].includes(a))return false;const r=flowRun(),rw=r?.reward;if(!rw?.shop||!equipmentReady())return true;
    if(a==='shop-refresh'){if(flowConfirm)return true;const cfg=EV.data.events[rw.sourceId],max=cfg.arrParam.length-2,cost=cfg.arrParam[Math.min(2+rw.refreshes,cfg.arrParam.length-1)];if(rw.refreshes>=max)return true;if(state.gold<cost){toast('灵石不足，刷新失败');return true;}state.gold-=cost;rw.refreshes++;chosen=null;stockShop();eventRecord('商店刷新','消耗 '+cost+' 灵石');}
    else {const p=flowConfirm;if(p?.type!=='shop-buy')return true;const inst=state.inventory.find(i=>i.uid===p.uid&&i.offer===rw.token);if(!inst||inst.salePrice==null)return true;if(state.gold<inst.salePrice){toast('灵石不足');return true;}if(!fits(inst,p.x,p.y,p.rotation)){toast('此处空间不足');return true;}state.gold-=inst.salePrice;delete inst.salePrice;inst.x=p.x;inst.y=p.y;inst.rotation=p.rotation;eventRecord('购买法宝',itemById.get(inst.id).name+'已入包');chosen=null;flowConfirm=null;}
    save();refreshFlow();return true;
  }
  function depart(){const r=flowRun();if(!r||r.phase!=='prepare')return;r.config.teacherStars=Object.fromEntries(TR.carried(state).map(id=>[id,state.teacherStars?.[id]??0]));flowConfirm=null;r.hp=stats().hp;r.phase='node-ready';r.popup=null;r.prepare=null;save();beginNode();}
  function beginNode(){const r=flowRun();if(!r||battle||r.popup||r.reward)return;const n=flowRoute()[r.step];r.sourceSteps=0;r.phase='event';r.history.push('第 '+(r.step+1)+' 关 · '+plain(n.szName));let tasks=[];const type=n.iTravelType;
    if(type===0)tasks=[{type:'story',title:'初入仙途',text:hero().name+'拜入宗门，携法宝与功法踏上历练。山水天地，机缘自寻。'}];
    else if(type===19)tasks=EV.tasks(200011,hero().name);
    else if(type===8)tasks=EV.tasks(700010,hero().name);
    else if(type===10)tasks=[{type:'story',title:'发现法宝匣',text:'山间拾得法宝匣，打开后可将合用的法宝挪入棋盘。'},{type:'equipment',total:2,title:'法宝机缘'}];
    else if([3,4,5].includes(type))tasks=[{type:'story',title:type===5?'首领现身':type===4?'精英拦路':'前路有敌',text:'前方妖气盘踞，法宝灵光已起。点击继续迎敌。'},{type:'battle'}];
    else if([2,14].includes(type))tasks=[{type:'ability',title:'神通领悟'}];
    else if(type===11)tasks=[{type:'attribute',title:'歇息疗伤',text:'山泉沁心，恢复部分生命。',heal:'half'}];
    else if([7,15].includes(type))tasks=EV.tasks(r.eventLibraryVersion!==18?EventLibrary.choose(r,[3,4,10,12,14,19,20]):600010,hero().name);
    else if(type===16)tasks=EV.tasks(r.eventLibraryVersion!==18?EventLibrary.choose(r,[18]):310410,hero().name);
    else if(type===18)tasks=EV.tasks(EventLibrary.choose(r,[12,27]),hero().name);
    else if(type===6)tasks=[{type:'wheel',title:'机缘转盘',rolled:false}];
    else if(type===1)tasks=[{type:'godexam',title:'渡劫突破'}];
    else if(type===20)tasks=[{type:'wheel',title:'老祖传功',rolled:false}];
    else if(type===9){return finishWander(false);}else tasks=[{type:'story',title:'山间机缘',text:plain(n.szName)}];
    r.queue=tasks;advanceFlowQueue();
  }
  function advanceFlowQueue(){const r=flowRun();if(!r)return;r.popup=null;flowConfirm=null;const task=r.queue.shift();if(!task){r.phase='node-done';save();refreshFlow();return;}
    if(handleSourceTask(task))return;if(task.type==='shop'){openShop(task);return;}if(task.type==='source-health'){r.hp=Math.max(1,Math.min(stats().hp,Math.floor(r.hp*(1+task.rate/10000)+task.flat)));save();return advanceFlowQueue();}if(task.type==='equipment'){openReward(task);return;}if(task.type==='battle'){startBattle();return;}
    if(task.type==='attribute'){task.elapsed=0;}if(task.type==='attribute'&&task.heal){const before=r.hp;if(task.heal==='full')r.hp=stats().hp;else if(task.heal==='half')r.hp=Math.min(stats().hp,r.hp+Math.round(stats().hp*.3));else r.hp=Math.min(stats().hp,r.hp+Math.round((stats().hp-r.hp)*.1));task.rows=[{label:'生命',value:Math.round(r.hp-before)}];(r.records=r.records||[]).push({step:r.step,title:task.title,text:'调息恢复 '+Math.round(r.hp-before)+' 生命。'});task.text+=(r.hp>before?' 生命 +'+Math.round(r.hp-before):' 当前生命已充足。');}
    if(task.type==='story'){r.records=r.records||[];r.records.push({step:r.step,title:task.title,text:task.text});}EV.init(task,r,state);
    r.phase='event';r.popup=task;save();refreshFlow();
  }
  function openReward(task){const r=flowRun();r.phase='reward';r.rewardView='equipment';r.reward={title:task.title||'获得法宝',quality:task.quality,ids:task.ids,batch:0,total:task.total||1,token:r.token+'-node'+r.step+'-batch0'};createRewardBatch();save();refreshFlow();}
  function createRewardBatch(){const r=flowRun(),rw=r.reward;if(state.inventory.some(i=>i.offer===rw.token))return;const q=rw.quality|| (rw.title.includes('血')||flowRoute()[r.step].iTravelType===5?4:flowRoute()[r.step].iTravelType===4?3:2);const base=D.items.filter(i=>i.quality<=q&&i.quality>=(rw.title.includes('血')?3:1)&&i.id>=110000&&i.id<180000);const ids=rw.ids?.filter(id=>itemById.has(id))?.length?rw.ids.filter(id=>itemById.has(id)):r.step===2&&rw.batch===0?[110101,110103,120101]:r.step===2&&rw.batch===1?[110103,120103,110201]:[0,1,2].map((_,i)=>base[(r.step*7+rw.batch*11+i*3+r.seed)%base.length].id);for(const id of ids)if(itemById.has(id))state.inventory.push({uid:++uid,id,x:null,y:null,rotation:0,offer:rw.token});}
  function finishReward(){const r=flowRun();if(!r?.reward)return;const remaining=state.inventory.filter(i=>i.offer===r.reward.token&&i.x===null&&i.salePrice==null);if(remaining.some(i=>itemById.get(i.id).quality>=5)){flowConfirm={type:'discard',count:remaining.length};syncFlowDialog(true);return;}beginRewardAdvance();}
  function beginRewardAdvance(){const r=flowRun();if(!r?.reward||r.pending)return;const remaining=state.inventory.filter(i=>i.offer===r.reward.token&&i.x===null&&i.salePrice==null);if(!remaining.length)return commitRewardBatch();r.pending={kind:'reward-clear',elapsed:0,duration:1.5};save();refreshFlow();const target=$('#w-reforge-sink').getBoundingClientRect();document.querySelectorAll('#w-reward .w-item').forEach(el=>{const b=el.getBoundingClientRect();el.style.setProperty('--clear-x',(target.x+target.width/2-b.x-b.width/2)+'px');el.style.setProperty('--clear-y',(target.y+target.height/2-b.y-b.height/2)+'px');});}
  function commitRewardBatch(){const r=flowRun();if(!r?.reward)return;const token=r.reward.token,kept=state.inventory.filter(i=>i.offer===token&&i.x!==null).length;(r.records=r.records||[]).push({step:r.step,title:'法宝机缘',text:'第 '+(r.reward.batch+1)+' 批法宝整理完毕，'+kept+' 件收入行囊。'});const discarded=state.inventory.filter(i=>i.offer===token&&i.x===null&&i.salePrice==null);for(const item of discarded)WT.recycle(state,item.uid);state.inventory=state.inventory.filter(i=>i.offer!==token||i.x!==null);for(const i of state.inventory)if(i.offer===token)delete i.offer;chosen=null;flowConfirm=null;if(r.reward.batch+1<r.reward.total){r.reward.batch++;r.reward.token=r.token+'-node'+r.step+'-batch'+r.reward.batch;createRewardBatch();save();refreshFlow();}else{const supplemental=r.reward.supplemental,resumePhase=r.reward.resumePhase;r.reward=null;delete r.rewardView;gridMode=false;if(supplemental){r.phase=resumePhase;save();refreshFlow();}else advanceFlowQueue();}}
  function finishWander(defeat){const r=flowRun();if(!r||r.settled)return;const late=r.step>=12,gold=CombatEffects.bonus(state,defeat?Math.floor((late?600:500)/2):(late?600:500),5031),crystal=CombatEffects.bonus(state,defeat?Math.floor((late?120:100)/2):(late?120:100),5032);state.gold+=gold;state.crystal=(state.crystal||0)+crystal;r.earned+=gold;r.finalReward={gold,crystal};if(r.early){const rate=(r.step+1)/flowRoute().length;const g=Math.floor(gold*rate),c=Math.floor(crystal*rate);state.gold-=gold-g;state.crystal-=crystal-c;r.earned-=gold-g;r.finalReward={gold:g,crystal:c};}r.settled=true;r.phase=defeat?'defeat':'complete';r.popup={type:'result'};r.reward=null;r.queue=[];battle=null;save();refreshFlow();}
  function flowBattleStart(){const r=flowRun(),s=stats(),type=flowRoute()[r.step].iTravelType,boss=type===5,elite=type===4,mult=1+state.cleared*.12,hp=Math.round((330+Math.floor(r.step/3)*100)*(boss?1.45:elite?1.2:1)*mult);battle={entryDuration:AppearanceMotion.duration(hero().skin?.[9],'begin'),elapsed:0,playerHp:Math.min(r.hp??s.hp,s.hp),playerMax:s.hp,enemyHp:hp,enemyMax:hp,playerAtk:s.atk,playerDef:s.def,playerSpeed:s.speed||30,enemySpeed:30,enemyAtk:Math.round((24+r.step*2)*mult),cooldown:0,playerInterval:.85/Math.max(.1,(s.speed||30)/30),enemyCooldown:.4,round:0,boss,hit:'',attack:'',visual:{player:null,enemy:null,effects:[]}};r.popup=null;r.phase='battle';log=['弟子入阵，法宝灵光流转。'];for(const id of ['disciple',boss?visualSetting().boss:'enemy'])for(const pose of ['idle','atk','hit'])image('assets/'+id+'-'+pose+'-sheet.png');save();render();}
  function flowBattleEnd(won){const r=flowRun();r.lastBattleReport={won,teacherAttributes:TR.attributes(state),teacherAudit:TR.audit(state),hits:battle.damageTrace||[],pet:battle.petTrace||[],effects:battle.effectTrace||[],provenance:"local-damage-adapter"};r.hp=Math.max(0,battle.playerHp);battle=null;delete r.battleSnapshot;if(!won)return finishWander(true);const gold=CombatEffects.bonus(state,35+r.step*12,5031);state.gold+=gold;state.insight+=8;r.earned+=gold;const healed=Math.round((stats().hp-r.hp)*.1);r.hp=Math.min(stats().hp,r.hp+healed);const tail=r.sourceBattle?r.queue:[];r.sourceBattle=false;r.queue=[{type:'story',title:'斗法获胜',text:'获得 '+gold+' 灵石、8 悟道；调息恢复 '+healed+' 生命。发现战利法宝，点击继续查看。'},{type:'equipment',title:'战利法宝',total:flowRoute()[r.step].iTravelType===3?1:2},...tail];advanceFlowQueue();}
  function flowSeedSlot(seed,slot){return `<button class="w-seed-slot ${flowSlot===slot?'active':''}" data-flow="slot" data-value="${slot}" aria-label="${slot==='seed'?'主修':'辅修'}功法">${seed?`<img src="${seed.icon}" alt="${escape(seed.name)}">`:'<span>未携带</span>'}<b>${slot==='seed'?'主修':'辅修'}</b></button>`;}
