    dlg.dataset.type=p.type;$('#w-dialog-body').innerHTML=`<div class="w-dialog-head"><h2 id="w-dialog-title">${escape(title)}</h2>${['book','bag-info','book-item','bag-trait','grid'].includes(p.type)?'<button class="wt-close" data-flow="utility-close" aria-label="关闭"></button>':''}</div><div class="w-dialog-content">${body}</div><div class="w-dialog-actions">${footer}</div>`;$('#w-disciple')?.addEventListener('change',e=>flowAction('disciple',e.target.value));if(!dlg.open)dlg.showModal();
